package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Complex_tanh_TriageGen3Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testTanh_NaN() {
        Complex c = Complex.NaN;
        Complex result = c.tanh();
        assertTrue("Result should be NaN", result.isNaN());
    }

    @Test
    public void testTanh_Zero() {
        Complex c = new Complex(0.0, 0.0);
        Complex result = c.tanh();
        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_RealOnly() {
        // tanh(x) for real x
        double x = 1.0;
        Complex c = new Complex(x, 0.0);
        Complex result = c.tanh();

        double expectedReal = Math.tanh(x);
        assertEquals(expectedReal, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_ImaginaryOnly() {
        // tanh(iy) = i * tan(y)
        double y = 0.5;
        Complex c = new Complex(0.0, y);
        Complex result = c.tanh();

        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(Math.tan(y), result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_Complex() {
        // Test with a standard complex number
        double re = 0.5;
        double im = 0.5;
        Complex c = new Complex(re, im);
        Complex result = c.tanh();

        // Manual calculation using the formula provided in the method:
        // real2 = 2 * 0.5 = 1.0
        // imag2 = 2 * 0.5 = 1.0
        // d = cosh(1.0) + cos(1.0)
        // expectedReal = sinh(1.0) / d
        // expectedImag = sin(1.0) / d

        double real2 = 1.0;
        double imag2 = 1.0;
        double d = Math.cosh(real2) + Math.cos(imag2);
        double expectedReal = Math.sinh(real2) / d;
        double expectedImag = Math.sin(imag2) / d;

        assertEquals(expectedReal, result.getReal(), EPSILON);
        assertEquals(expectedImag, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_LargeReal() {
        // As real -> infinity, tanh(z) -> 1
        Complex c = new Complex(100.0, 0.0);
        Complex result = c.tanh();
        assertEquals(1.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_Infinite() {
        // Test behavior with infinity
        Complex c = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Complex result = c.tanh();
        // Depending on implementation, tanh(inf) is 1.0 or NaN. 
        // Based on the provided code, cosh(inf) is inf, sinh(inf) is inf. inf/inf is NaN.
        assertTrue(result.isNaN() || Math.abs(result.getReal() - 1.0) < EPSILON);
    }
}
